package dev.septemberz;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
class AnnouncementToolsTest{@Test void templateRequiresEveryField(){var t=new AnnouncementTemplate("event","{{event}} update","Meet in {{place}}");var a=t.render(Map.of("event","Robotics","place","Lab"),"Students",LocalDate.of(2030,9,16),"demo@example.test");assertEquals("Robotics update",a.title());assertThrows(IllegalArgumentException.class,()->t.render(Map.of("event","x"),"Students",a.deadline(),a.contact()));}@Test void audienceExpansionAndVisibility(){var p=new AudiencePolicy();assertEquals(3,p.recipients("all").size());var a=new Announcement("x","y","Families",LocalDate.of(2030,1,1),"x@example.test");assertTrue(p.visibleTo(a,"families"));assertFalse(p.visibleTo(a,"students"));}@Test void publishingAvoidsWeekend(){var a=new Announcement("x","y","All",LocalDate.of(2030,9,16),"x@example.test");assertEquals(LocalDate.of(2030,9,13),new PublishingCalendar().recommendedPublishDate(a,1));}}
